#include <algorithm>
#include <cstdio>
#include <utility>
#include <vector>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<std::pair<long long, long long>> pairs;
    for (int i = 0; i < n; i++) {
        long long k = 0;
        long long v = 0;
        if (std::scanf("%lld %lld", &k, &v) != 2) return 1;
        if (k < -1000 || k > 1000 || v < -1000 || v > 1000) return 1;
        pairs.emplace_back(k, v);
    }
    std::sort(pairs.begin(), pairs.end());
    for (const auto& entry : pairs) {
        std::printf("%lld:%lld\n", entry.first, entry.second);
    }
    return 0;
}
